head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.pageSize = 10; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vPAGENO = 0;
scwin.vScrenID = "ULDINS21300.xml";

// 발행기관 조회처리 추가
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vsCoPopGb = "SCH";
scwin.vSelObj;
scwin.vRowCount = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_SDATE, vCurDate.substring(0, 4) + "0101"); // 연초날짜
    $c.stf.setObjectValue(edt_EDATE, $c.ut.cGetToday2());

    //setObjectValue(rdo_MKT_ID, js_market);
    //js_market = "6"

};





/********************************************
 * 선납잔액 조회(발행기관별)
 *********************************************/
scwin.fn_readPrepayChg = function() {
    //선납잔액 조회
    var url = "/PrepayInfoAction.do?method=readPrepayChg";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};


/********************************************** 
 * 함수명   : fn_readAllPrepayChg
 * 설명       : 선납잔액전체 조회
 ***********************************************/
scwin.fn_readAllPrepayChg = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=PREPAYINFO_21300_INOUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.prepaysum.hist";
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};


/********************************************
 * 선납금 리스트 조회 - 입출금현황
 *********************************************/
scwin.fn_listPrepayChg = function() {
    //var argv = fn_listPrepayChg.arguments;
    //var argc = fn_listPrepayChg.arguments.length;
    //vPAGENO = (argc == 0) ? 0 : vPAGENO = argv[0];

    $c.cm.ShowWin(grd_Grid);
    var url = "/PrepayInfoAction.do?method=listPrepayChg";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(url);
    dts_PassList.DataID = encodeURI(url);
    dts_PassList.Reset();
};


/********************************************** 
 * 함수명   : fn_listBalanceByIsurCd
 * 설명       : 회사별잔고현황
 ***********************************************/
scwin.fn_listBalanceByIsurCd = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=PREPAYINFO_21300_INOUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.balanceByIsurCd" + "&{P}ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}SDATE=" + $c.stf.getObjectValue(edt_SDATE) + "&{P}EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    dts_PassList2.DataID = encodeURI(url);
    dts_PassList2.reset();
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 설정한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드  
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명     

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_popupPrepayChg
 * 설명       : 발행기관별 선납금을 조회한다.
 ***********************************************/
scwin.fn_popupPrepayChg = async function(row, colid) {
    if (colid == "COM_NM") {
        var vISUR_CD = dts_PassList.getCellData(row, "ISUR_CD"); // ISUR_CD
        await $c.frame.CreateDialogFrame("NEWPASS_READ|ISUR_CD=" + vISUR_CD, "/etc/ULDINS21301.gfm", "선납금 조회", 10, 10, 820, 580, "window");
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_popupPrepayChg(row, colid);
};
scwin.btn_New_onclick = async function() {
    await $c.frame.CreateDialogFrame("NEWPASS_READ|ISUR_CD=" + "", "/etc/ULDINS21302.gfm", "선납금 등록", 10, 10, 820, 690, "window");
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    scwin.fn_Init();
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    if (vTp == 7) {
        //전체
        $c.stf.setObjectValue(edt_SDATE, '00010101');
        $c.stf.setObjectValue(edt_EDATE, '99991231');
    } else {
        $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    if (tab_IsurInfo.getSelectedTabIndex() == "1") {
        $c.data.downloadGridViewExcel(grd_Grid, "입출금현황", "", "8");
    } else if (tab_IsurInfo.getSelectedTabIndex() == "2") {
        $c.data.downloadGridViewExcel(grd_Grid2, "회사별잔고현황", "", "8");
    }
};
scwin.dts_PassList_OnLoadCompleted = function(rowcount) {
    if (dts_PassList.errorMsg) {
        $c.win.alert(dts_PassList.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    if (txb_ISUR_CD.getValue() == "") {
        scwin.fn_readAllPrepayChg(); //발행기관 전체 총선납액,잔액 조회

    } else {
        scwin.fn_readPrepayChg(); //발행기관별 조회 시 총선납액,잔액 조회

    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_PassList2_OnLoadCompleted = function(rowcount) {
    if (dts_PassList2.errorMsg) {
        $c.win.alert(dts_PassList2.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    if (txb_ISUR_CD.getValue() == "") {
        scwin.fn_readAllPrepayChg(); //발행기관 전체 총선납액,잔액 조회

    } else {
        scwin.fn_readPrepayChg(); //발행기관별 조회 시 총선납액,잔액 조회

    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_PassList_OnLoadError = function() {
    $c.stf.alert_error(dts_PassList);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txb_COM_NM2, false);
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_Init();
    scwin.fn_listPrepayChg();
};
scwin.btn_Search_onclick = function() {
    if (tab_IsurInfo.getSelectedTabIndex() == "1") {
        scwin.fn_listPrepayChg();
    } else if (tab_IsurInfo.getSelectedTabIndex() == "2") {
        scwin.fn_listBalanceByIsurCd();
    }
};
scwin.img_SRCH_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_SRCH_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_SRCH_ISUR_CD2_onclick = function() {
    txb_ISUR_CD.setValue("");
    txb_SRCH_ISUR_NM.setValue("");
    txb_TOT_PREPAY_AMT.setValue("");
    txb_PREPAY_BAL.setValue("");
};
scwin.dts_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_detail);
};
scwin.tab_IsurInfo_OnSelChanged = function(nIndex) {
    if (nIndex == "1") {
        $c.stf.showObj(btn_New, true);
        scwin.fn_listPrepayChg();
    } else if (nIndex == "2") {
        $c.stf.showObj(btn_New, false);
        scwin.fn_listBalanceByIsurCd();
    }
};
